static const SmoothFont SF76 = {60, SF76_GLYPHS, SF76_BMP};

static constexpr int SMOOTH_FONT_COUNT = 6;
static const SmoothFont *const SMOOTH_FONTS[SMOOTH_FONT_COUNT] = {
  &SF12, &SF16, &SF22, &SF30, &SF40, &SF54
};


// Map UTF-8 or ASCII char at str[i] to glyph index (0..96); advances i for multi-byte UTF-8
static inline int smoothNextGlyphIdx(const char *s, int &i) {
  uint8_t c = (uint8_t)s[i];
  if (c == 0) return -1;
  if (c >= 0x20 && c <= 0x7E) {
    i += 1;
    return (int)(c - 0x20);
  }
  // UTF-8 2-byte: U+00B0 (°) = 0xC2 0xB0, U+00B7 (·) = 0xC2 0xB7
  if (c == 0xC2 && (uint8_t)s[i + 1] == 0xB0) { i += 2; return 95; }
  if (c == 0xC2 && (uint8_t)s[i + 1] == 0xB7) { i += 2; return 96; }
  // Skip unknown UTF-8 continuation bytes
  i += 1;
  while (((uint8_t)s[i] & 0xC0) == 0x80) i++;
  return 0; // space fallback
}

// Pick the best matching SmoothFont for a desired cap height (px)
static inline const SmoothFont &smoothPickFont(float targetCapH) {
  int best = 0;
  float bestErr = 1e9f;
  for (int k = 0; k < SMOOTH_FONT_COUNT; k++) {
    float err = fabsf((float)SMOOTH_FONTS[k]->capH - targetCapH);
    if (err < bestErr) { bestErr = err; best = k; }
  }
  return *SMOOTH_FONTS[best];
}

// Map legacy gfx->setTextSize(1..7) to clean modern SmoothFont
static inline const SmoothFont &smoothFontForLegacySize(int size) {
  if (size <= 1) return SF12;
  if (size == 2) return SF16;
  if (size == 3) return SF22;
  if (size == 4) return SF30;
  if (size == 5) return SF40;
  return SF54; // size >= 6
}

static inline uint16_t smoothBlend565(uint16_t bg, uint16_t fg, uint8_t a4) {
  if (a4 >= 15) return fg;
  if (a4 == 0) return bg;
  uint32_t t = (uint32_t)a4 * 17u; // 0..255
  uint32_t inv = 256u - t;
  uint32_t r = (((bg >> 11) & 31u) * inv + ((fg >> 11) & 31u) * t) >> 8;
  uint32_t g = (((bg >> 5)  & 63u) * inv + ((fg >> 5)  & 63u) * t) >> 8;
  uint32_t b = ((bg         & 31u) * inv + (fg         & 31u) * t) >> 8;
  return (uint16_t)((r << 11) | (g << 5) | b);
}

static inline int smoothMeasureWidth(const SmoothFont &f, const char *s, bool mapDegree = false) {
  if (!s) return 0;
  int w = 0;
  int i = 0;
  while (s[i]) {
    int idx;
    if (mapDegree && (s[i] == '*' || s[i] == '^')) { idx = 95; i++; }
    else idx = smoothNextGlyphIdx(s, i);
    if (idx >= 0 && idx < 97) w += f.glyphs[idx].xAdv;
  }
  return w;
}

static inline void smoothBlitGlyph(uint16_t *fb, int W, int H, const SmoothFont &f, int idx, int penX, int topY, uint16_t color) {
  const SmoothGlyph &g = f.glyphs[idx];
  if (g.w == 0 || g.h == 0) return;
  int gx0 = penX + g.xOff;
  int gy0 = topY + g.yOff;
  const uint8_t *src = f.bitmap + g.offset;
  int gw = g.w, gh = g.h;
  for (int row = 0; row < gh; row++) {
    int py = gy0 + row;
    if (py < 0 || py >= H) continue;
    uint16_t *dstRow = fb + py * W;
    int rowPixOff = row * gw;
    for (int col = 0; col < gw; col++) {
      int px = gx0 + col;
      if (px < 0 || px >= W) continue;
      int pIdx = rowPixOff + col;
      uint8_t byteVal = src[pIdx >> 1];
      uint8_t a4 = (pIdx & 1) ? (byteVal & 0x0F) : (byteVal >> 4);
      if (a4 == 0) continue;
      dstRow[px] = (a4 >= 15) ? color : smoothBlend565(dstRow[px], color, a4);
    }
  }
}

// Draw smooth anti-aliased string at (x, y)
// alignH: 0 = left, 1 = center, 2 = right
// alignV: 0 = top (cap top = y), 1 = vertical center (cap center = y)
static inline void smoothDrawText(const SmoothFont &f, const char *s, int x, int y, uint16_t color,
                                  int alignH = 0, int alignV = 0, bool mapDegree = false) {
  if (!s || !s[0]) return;
  uint16_t *fb = gfx->getFramebuffer();
  if (!fb) return;
  const int W = LCD_WIDTH;
  const int H = LCD_HEIGHT;
  int tw = (alignH != 0) ? smoothMeasureWidth(f, s, mapDegree) : 0;
  int penX = (alignH == 1) ? (x - tw / 2) : (alignH == 2 ? (x - tw) : x);
  int topY = (alignV == 1) ? (y - (int)f.capH / 2) : y;

  int i = 0;
  while (s[i]) {
    int idx;
    if (mapDegree && (s[i] == '*' || s[i] == '^')) { idx = 95; i++; }
    else idx = smoothNextGlyphIdx(s, i);
    if (idx >= 0 && idx < 97) {
      smoothBlitGlyph(fb, W, H, f, idx, penX, topY, color);
      penX += f.glyphs[idx].xAdv;
    }
  }
}

// Draw smooth anti-aliased string with a crisp dark halo/outline (for floating map HUD)
static inline void smoothDrawTextOutlined(const SmoothFont &f, const char *s, int x, int y, uint16_t color,
                                          uint16_t outlineColor = 0x0000, int alignH = 1, int alignV = 0, int radius = 2) {
  if (!s || !s[0]) return;
  uint16_t *fb = gfx->getFramebuffer();
  if (!fb) return;
  const int W = LCD_WIDTH;
  const int H = LCD_HEIGHT;
  int tw = (alignH != 0) ? smoothMeasureWidth(f, s, false) : 0;
  int penX0 = (alignH == 1) ? (x - tw / 2) : (alignH == 2 ? (x - tw) : x);
  int topY = (alignV == 1) ? (y - (int)f.capH / 2) : y;

  // 8-direction crisp halo pass
  static const int8_t dx8[8] = {-1, 0, 1, -1, 1, -1, 0, 1};
  static const int8_t dy8[8] = {-1, -1, -1, 0, 0, 1, 1, 1};
  int r = (radius <= 1) ? 1 : 2;
  for (int d = 0; d < 8; d++) {
    int ox = dx8[d] * r;
    int oy = dy8[d] * r;
    int penX = penX0 + ox;
    int i = 0;
    while (s[i]) {
      int idx = smoothNextGlyphIdx(s, i);
      if (idx >= 0 && idx < 97) {
        smoothBlitGlyph(fb, W, H, f, idx, penX, topY + oy, outlineColor);
        penX += f.glyphs[idx].xAdv;
      }
    }
  }
  // Foreground crisp pass
  int penX = penX0;
  int i = 0;
  while (s[i]) {
    int idx = smoothNextGlyphIdx(s, i);
    if (idx >= 0 && idx < 97) {
      smoothBlitGlyph(fb, W, H, f, idx, penX, topY, color);
      penX += f.glyphs[idx].xAdv;
    }
  }
}

